      if (session && item) undo.set(undoKeyOf(session), { item, at })
      return { id }
    }),
    implement(removeNotes, ({ ids }, { session }) => {
      const items = ownListOf(session)
      const removed = items.filter((item) => ids.includes(item.id) && !item.archived).map((item) => item.id)
      for (const id of removed) items.splice(items.findIndex((item) => item.id === id), 1)
      forget(session)
      return { ids: removed }
    }),
    implement(archiveNotes, ({ ids }, { session }) => {
      const archived = listOf(session).filter((item) => ids.includes(item.id) && !item.archived)
      for (const item of archived) item.archived = true
      forget(session)
      return { ids: archived.map((item) => item.id) }
    }),
    implement(lastDeleted, (_, { session, fail }) => {
      if (!session) return fail('Unauthorized', {})
      const entry = undo.get(undoKeyOf(session))
      return entry ? { title: entry.item.title } : null
    }),
    implement(undoDelete, (_, { fail, session }) => {
      const entry = session ? undo.get(undoKeyOf(session)) : undefined
      if (!session || !entry) return fail('NothingToUndo', {})
      const items = ownListOf(session)
      items.splice(Math.min(entry.at, items.length), 0, entry.item)
      forget(session)
      return view(entry.item)
    }),
    implement(renameNote, ({ id, title }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const clean = title.trim()
      if (items.some((entry) => entry.id !== id && entry.title.toLowerCase() === clean.toLowerCase()))
        return fail('Duplicate', { title: clean })
      item.title = clean
      forget(session)
      return view(item)
    }),
    implement(updateNote, ({ id, title, body }, { fail, session }) => {
      const items = listOf(session)
      const item = items.find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      const cleanTitle = title.trim()
      // A form post sends line breaks as CRLF; count and keep them as one character, like the browser's maxlength.
      const cleanBody = body.replace(/\r\n?/g, '\n').trim()
      const titleError =
        cleanTitle.length === 0 ? 'Write a title first'
          : cleanTitle.length > 60 ? 'Use at most 60 characters'
          : items.some((entry) => entry.id !== id && entry.title.toLowerCase() === cleanTitle.toLowerCase()) ? 'You already have a note with this title'
          : null
      const bodyError = cleanBody.length > 1000 ? 'Use at most 1000 characters in the body' : null
      if (titleError !== null || bodyError !== null)
        return fail('Invalid', { message: 'Check the note', fields: { title: titleError, body: bodyError } })
      item.title = cleanTitle
      item.body = cleanBody
      forget(session)
      return { ...item, sharedWith: [...item.sharedWith] }
    }),
    implement(togglePin, ({ id }, { fail, session }) => {
      const item = listOf(session).find((entry) => entry.id === id)
      if (!item) return fail('NotFound', { id })
      if (item.archived) return fail('Archived', { id })
      item.pinned = !item.pinned
      forget(session)
      return view(item)
    }),
  ]
}
import type { Item } from './undo.ts'

// Every user's notes, by lower-cased name, with who shared them and when they added them.
export type NoteStore = {
  notes: Map<string, Item[]>
  // Display name of each owner who has shared a note, by store key.
  owners: Map<string, string>
  // Times of the adds that went through, per user.
  added: Map<string, number[]>
  // The highest note number each user has ever had; numbers are never reused.
  numbers: Map<string, number>
  nextId: () => string
  nextNumber: (key: string) => number
}

export function createNoteStore(): NoteStore {
  let seq = 0
  const nextId = () => `n${++seq}`
  const numbers = new Map<string, number>()
  const nextNumber = (key: string) => {
    const number = (numbers.get(key) ?? 0) + 1
    numbers.set(key, number)
    return number
  }
  // Existing notes are numbered in the order they were added, oldest first.
  const seed = (key: string, notes: [string, string][]) => {
    const items = notes.map(([title, createdAt]) => ({ id: nextId(), number: 0, title, body: '', pinned: false, createdAt, archived: false, sharedWith: [] as string[] }))
    for (const item of [...items].sort((a, b) => a.createdAt.localeCompare(b.createdAt))) item.number = nextNumber(key)
    return items
  }
  return {
    notes: new Map<string, Item[]>([
      ['ada', seed('ada', [['Buy milk', '2026-01-15T09:00:00.000Z'], ['Call Bob', '2026-01-14T09:00:00.000Z']])],
      ['bob', seed('bob', [["Bob's secret", '2026-01-10T09:00:00.000Z']])],
    ]),
    owners: new Map(),
    added: new Map(),
    numbers,
    nextId,
    nextNumber,
  }
}

// Drops everything kept for a user: their notes (archived and shared ones included), sharing, add history and note numbers.
export const purgeUser = (store: NoteStore, key: string) => {
  store.notes.delete(key)
  store.owners.delete(key)
  store.added.delete(key)
  store.numbers.delete(key)
}
export type Item = { id: string; number: number; title: string; body: string; pinned: boolean; createdAt: string; archived: boolean; sharedWith: string[] }

// The most recent delete per user, kept until it is undone, the user's notes change again or the user signs out.
export type UndoStore = Map<string, { item: Item; at: number }>

export const createUndoStore = (): UndoStore => new Map()

export const undoKeyOf = (session: { user: string }) => session.user.toLowerCase()
import type { Implement } from '@hozu/data'
import { ui } from '@hozu/core'
import { home, login } from '../../routes.ts'
import { me, removeAccount, root, signIn, signOut } from './model.ts'
import { type UndoStore, undoKeyOf } from '../notes/undo.ts'
import { type UserDirectory, isAdmin } from './users.ts'
import { type NoteStore, purgeUser } from '../notes/store.ts'

export function accountResolvers<Env>(implement: Implement<{ user: string }, Env>, undo: UndoStore, users: UserDirectory, notes: NoteStore) {
  return [
    implement(me, (_, { session, fail }) => (session ? { name: session.user, admin: isAdmin(session) } : fail('Unauthorized', {}))),
    implement(root, (_, { session, redirect }) => redirect(session ? ui.link(home, null) : ui.link(login, null))),
    implement(signIn, ({ name }, { setSession }) => {
      setSession({ user: name.trim() })
      users.set(name.trim().toLowerCase(), name.trim())
      return {}
    }),
    implement(signOut, (_, { session, setSession }) => {
      if (session) undo.delete(undoKeyOf(session))
      setSession(null)
      return {}
    }),
    implement(removeAccount, (_, { session, setSession }) => {
      if (session) {
        const key = session.user.trim().toLowerCase()
        purgeUser(notes, key)
        users.delete(key)
        undo.delete(undoKeyOf(session))
      }
      setSession(null)
      return {}
    }),
  ]
}
// Everyone who has signed in, by lower-cased name, with the name they last signed in with.
export type UserDirectory = Map<string, string>

export const createUserDirectory = (): UserDirectory => new Map()

export const ADMIN = 'admin'

export const isAdmin = (session: { user: string }) => session.user.trim().toLowerCase() === ADMIN
